def topo_sort(nodes: list, edges: list[tuple]) -> list:
    if not nodes:
        return []

    node_set = set(nodes)
    in_degree = {node: 0 for node in nodes}
    adj = defaultdict(list)

    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError(f"Edge ({a}, {b}) references unknown node(s)")
        adj[a].append(b)
        in_degree[b] += 1

    # Use a sorted structure for tie-breaking (smallest available node)
    available = [node for node in nodes if in_degree[node] == 0]
    available.sort()

    result = []
    while available:
        # Pop the smallest available node
        node = available.pop(0)
        result.append(node)

        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                # Insert in sorted position
                available.append(neighbor)
                available.sort()

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

