class _Parser:
    def __init__(self, tokens: List[Tuple[str, float]]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Tuple[str, float]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return ('EOF', 0.0)

    def consume(self) -> Tuple[str, float]:
        tok = self.peek()
        self.pos += 1
        return tok

    def expect(self, expected_type: str) -> Tuple[str, float]:
        tok = self.peek()
        if tok[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {tok[0]}")
        return self.consume()

    def parse_expression(self) -> float:
        # expression := term (('+' | '-') term)*
        result = self.parse_term()
        while True:
            tok = self.peek()
            if tok[0] == '+':
                self.consume()
                right = self.parse_term()
                result += right
            elif tok[0] == '-':
                self.consume()
                right = self.parse_term()
                result -= right
            else:
                break
        return result

    def parse_term(self) -> float:
        # term := factor (('*' | '/') factor)*
        result = self.parse_factor()
        while True:
            tok = self.peek()
            if tok[0] == '*':
                self.consume()
                right = self.parse_factor()
                result *= right
            elif tok[0] == '/':
                self.consume()
                right = self.parse_factor()
                if right == 0.0:
                    raise ValueError("Division by zero")
                result /= right
            else:
                break
        return result

    def parse_factor(self) -> float:
        # factor := ('+' | '-') factor | primary
        tok = self.peek()
        if tok[0] == '+':
            self.consume()
            return self.parse_factor()
        elif tok[0] == '-':
            self.consume()
            return -self.parse_factor()
        else:
            return self.parse_primary()

    def parse_primary(self) -> float:
        # primary := NUMBER | '(' expression ')'
        tok = self.peek()
        if tok[0] == 'NUMBER':
            self.consume()
            return tok[1]
        elif tok[0] == '(':
            self.consume()
            result = self.parse_expression()
            self.expect(')')
            return result
        else:
            raise ValueError(f"Unexpected token: {tok[0]}")


def _tokenize(expr: str) -> List[Tuple[str, float]]:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch in '+-*/()':
            tokens.append((ch, 0.0))
            i += 1
        elif ch.isdigit() or ch == '.':
            # Parse number
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                if expr[j] == '.':
                    has_dot = True
                j += 1
            if j == i:
                raise ValueError(f"Invalid number at position {i}")
            num_str = expr[i:j]
            if num_str == '.':
                raise ValueError(f"Invalid number at position {i}")
            try:
                num_val = float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: {num_str}")
            tokens.append(('NUMBER', num_val))
            i = j
        else:
            raise ValueError(f"Unexpected character: {ch}")
    return tokens


def evaluate(expr: str) -> float:
    if not expr or not isinstance(expr, str):
        raise ValueError("Invalid expression")
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")
    parser = _Parser(tokens)
    result = parser.parse_expression()
    if parser.pos != len(tokens):
        raise ValueError("Unexpected tokens after expression")
    return result

