def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression string supporting + - * / parentheses,
    unary minus, integers and decimals, with correct precedence.
    """
    # Tokenizer
    def tokenize(s: str) -> List[str]:
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
                continue
            if ch in '+-*/()':
                tokens.append(ch)
                i += 1
            elif ch.isdigit() or ch == '.':
                # Number: digits and optional decimal point
                j = i
                has_dot = False
                while j < n and (s[j].isdigit() or s[j] == '.'):
                    if s[j] == '.':
                        if has_dot:
                            raise ValueError(f"Invalid number at position {i}")
                        has_dot = True
                    j += 1
                num_str = s[i:j]
                # Validate the number
                if num_str == '.':
                    # Allow .5 or 5. but not just .
                    # Actually, let's be more permissive: .5 is valid, 5. is valid
                    # But we need to check it's a valid float
                    try:
                        float(num_str)
                    except ValueError:
                        raise ValueError(f"Invalid number '{num_str}' at position {i}")
                tokens.append(num_str)
                i = j
            else:
                raise ValueError(f"Unexpected character '{ch}' at position {i}")
        return tokens

    # Parser using recursive descent
    # Grammar:
    # expr    -> term (('+' | '-') term)*
    # term    -> factor (('*' | '/') factor)*
    # factor  -> ('+' | '-') factor | primary
    # primary -> NUMBER | '(' expr ')'

    def parse(tokens: List[str]) -> float:
        pos = 0

        def peek() -> str:
            nonlocal pos
            if pos < len(tokens):
                return tokens[pos]
            return None

        def consume() -> str:
            nonlocal pos
            if pos >= len(tokens):
                raise ValueError("Unexpected end of expression")
            tok = tokens[pos]
            pos += 1
            return tok

        def parse_expr() -> float:
            val = parse_term()
            while peek() in ('+', '-'):
                op = consume()
                right = parse_term()
                if op == '+':
                    val += right
                else:
                    val -= right
            return val

        def parse_term() -> float:
            val = parse_factor()
            while peek() in ('*', '/'):
                op = consume()
                right = parse_factor()
                if op == '*':
                    val *= right
                else:
                    if right == 0:
                        raise ValueError("Division by zero")
                    val /= right
            return val

        def parse_factor() -> float:
            tok = peek()
            if tok == '+':
                consume()
                return parse_factor()
            elif tok == '-':
                consume()
                return -parse_factor()
            else:
                return parse_primary()

        def parse_primary() -> float:
            tok = peek()
            if tok is None:
                raise ValueError("Unexpected end of expression")
            if tok == '(':
                consume()
                val = parse_expr()
                if peek() != ')':
                    raise ValueError("Expected closing parenthesis")
                consume()
                return val
            elif tok in ('+', '-', '*', '/', ')'):
                raise ValueError(f"Unexpected token '{tok}'")
            else:
                # Must be a number
                num_str = consume()
                try:
                    return float(num_str)
                except ValueError:
                    raise ValueError(f"Invalid number '{num_str}'")

        result = parse_expr()
        if pos != len(tokens):
            raise ValueError(f"Unexpected token '{tokens[pos]}' after expression")
        return result

    # Handle empty or whitespace-only input
    if not expr or not expr.strip():
        raise ValueError("Empty expression")

    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")

    return parse(tokens)

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    n, m = len(a), len(b)
    # DP table for LCS lengths
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Backtrack to produce diff
    result: list[tuple[str, str]] = []
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i - 1] == b[j - 1]:
            result.append((' ', a[i - 1]))
            i -= 1
            j -= 1
        elif j > 0 and (i == 0 or dp[i][j - 1] >= dp[i - 1][j]):
            result.append((' +', b[j - 1]))
            j -= 1
        else:
            result.append(('-', a[i - 1]))
            i -= 1

    result.reverse()
    return result

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    n, m = len(a), len(b)
    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = dp[i + 1][j + 1] + 1
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    result: list[tuple[str, str]] = []
    i, j = 0, 0
    while i < n and j < m:
        if a[i] == b[j]:
            result.append((' ', a[i]))
            i += 1
            j += 1
        else:
            # Prefer deletion (move i) before insertion (move j)
            if dp[i + 1][j] >= dp[i][j + 1]:
                result.append(('-', a[i]))
                i += 1
            else:
                result.append(('+', b[j]))
                j += 1
    while i < n:
        result.append(('-', a[i]))
        i += 1
    while j < m:
        result.append(('+', b[j]))
        j += 1
    return result

